# Review minor 6: no bar reason, the dead Markdown label gone (its description through the entry's `describe`).
for lang, table in (("fr", fr), ("en", en)):
    bad += [f"{lang} still has {k}" for k in ("cmd.insert.needsBar", "insert.csvTable.markdown") if k in table]
